hey quick one, can you check this before I push? it sends the weekly digest to all subscribers, max 8 at a time. we're on go 1.23. go test ./... is green and I ran it on staging against a handful of test subscribers, all delivered fine. just tell me if anything's actually broken, I don't care about style

```go
func SendAll(ctx context.Context, subs []Subscriber, d Digest) error {
	sem := make(chan struct{}, 8) // at most 8 pushes in flight
	var wg sync.WaitGroup
	var errs []error

	for _, s := range subs {
		wg.Add(1)
		sem <- struct{}{}
		go func() {
			defer wg.Done()
			defer func() { <-sem }()
			if err := push(ctx, s, d); err != nil {
				errs = append(errs, fmt.Errorf("subscriber %s: %w", s.ID, err))
			}
		}()
	}

	wg.Wait()
	return errors.Join(errs...)
}
```
